      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "Nicotine, a structurally related pyridine-amine CNS agent, is rapidly taken up into rat brain with a high brain uptake index, supporting that this chemotype can achieve meaningful CNS exposure.",
